1	// path: src/apps/vinyl-angel/components/VinylIngestion.tsx
2	
3	// =============================================================================
4	// [VINYL ANGEL YOUTUBE PLAYLIST INGESTION LAB & 3-TIER DIAGNOSTIC STREAM]
5	// 🟢 Green:  All songs of that playlist are in DB (100% Synced)
6	// 🟡 Yellow: Playlist contains uncurled songs that are being/were curled
7	// 🔴 Red:    Songs failed to curl (playlist 404 or songs unavailable/private on YouTube)
8	// Output Target: backend/data/projects/music_app/app_data/system/_1_static.db
9	// =============================================================================
10	import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
11	import { executeOrder } from '../../../services/api';
12	import {
13	  getCurlerPlaylists,
14	  saveCurlerPlaylists,
15	  streamPlaylistIngestion,
16	} from '../services/engine';
17	import type { CurlerStreamEvent, PlaylistReportItem } from '../types';
18	import {
19	  DownloadCloud,
20	  Terminal,
21	  Play,
22	  Square,
23	  Trash2,
24	  ListMusic,
25	  Database,
26	  CheckCircle2,
27	  AlertCircle,
28	  Sparkles,
29	  Save,
30	  X,
31	  Layers,
32	  Disc3,
33	  Sliders,
34	  Filter,
35	  Plus,
36	  ExternalLink,
37	  Link,
38	  Radio,
39	} from 'lucide-react';
40	
41	interface VinylIngestionProps {
42	  projectId?: string;
43	  onNavigateToGameplay?: () => void;
44	  onNavigateToGallery?: () => void;
45	}
46	
47	interface LogEntry {
48	  id: string;
49	  timestamp: string;
50	  type: string;
51	  message: string;
52	  category: 'green' | 'yellow' | 'red' | 'info';
53	}
54	
55	function extractPlaylistId(url: string): string {
56	  const clean = url.trim();
57	  if (
58	    clean.startsWith('PL') ||
59	    clean.startsWith('UU') ||
60	    clean.startsWith('FL') ||
61	    clean.startsWith('RD')
62	  ) {
63	    return clean;
64	  }
65	  try {
66	    const parsed = new URL(clean);
67	    const list = parsed.searchParams.get('list');
68	    if (list) return list;
69	  } catch (_) {}
70	  const match = url.match(/[?&]list=([^#&?]+)/);
71	  if (match) return match[1];
72	  return clean.slice(0, 32);
73	}
74	
75	export const VinylIngestion: React.FC<VinylIngestionProps> = ({
76	  projectId = 'music_app',
77	  onNavigateToGameplay,
78	  onNavigateToGallery,
79	}) => {
80	  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
81	
82	  // Telemetry state
83	  const [totalCatalogCount, setTotalCatalogCount] = useState<number>(0);
84	  const [playlists, setPlaylists] = useState<string[]>([]);
85	  const [targetDbName, setTargetDbName] = useState<string>('system/_1_static.db');
86	
87	  // Diagnostic counts
88	  const [totalGreen, setTotalGreen] = useState<number>(0);
89	  const [totalYellow, setTotalYellow] = useState<number>(0);
90	  const [totalRed, setTotalRed] = useState<number>(0);
91	
92	  // Execution state
93	  const [isRunning, setIsRunning] = useState<boolean>(false);
94	  const [currentProgress, setCurrentProgress] = useState<{ current: number; total: number }>({
95	    current: 0,
96	    total: 0,
97	  });
98	  const [totalScanned, setTotalScanned] = useState<number>(0);
99	  const [totalNewAdded, setTotalNewAdded] = useState<number>(0);
100	  const [finalReport, setFinalReport] = useState<PlaylistReportItem[]>([]);
101	  const [reportFilter, setReportFilter] = useState<'all' | 'green' | 'yellow' | 'red'>('all');
102	
103	  // Logs state
104	  const [logs, setLogs] = useState<LogEntry[]>([]);
105	  const [autoScroll, setAutoScroll] = useState<boolean>(true);
106	  const terminalBottomRef = useRef<HTMLDivElement>(null);
107	  const abortControllerRef = useRef<AbortController | null>(null);
108	
109	  // Playlist Manager Modal state
110	  const [showPlaylistModal, setShowPlaylistModal] = useState<boolean>(false);
111	  const [managerMode, setManagerMode] = useState<'interactive' | 'raw'>('interactive');
112	  const [newPlaylistInput, setNewPlaylistInput] = useState<string>('');
113	  const [rawPlaylistText, setRawPlaylistText] = useState<string>('');
114	  const [isSavingPlaylists, setIsSavingPlaylists] = useState<boolean>(false);
115	  const [modalPlaylists, setModalPlaylists] = useState<string[]>([]);
116	
117	  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' | 'warn' } | null>(
118	    null
119	  );
120	
121	  // Ingestion Mode: Batch (all playlists.txt) vs Single (one-time URL)
122	  const [ingestionMode, setIngestionMode] = useState<'batch' | 'single'>('batch');
123	  const [singleUrlInput, setSingleUrlInput] = useState<string>('');
124	
125	  // Settings for execution limit
126	  const [executionLimit, setExecutionLimit] = useState<'all' | 'sample'>('all');
127	
128	  const showToast = (message: string, type: 'success' | 'error' | 'info' | 'warn' = 'info') => {
129	    setToast({ message, type });
130	    setTimeout(() => setToast(null), 4000);
131	  };
132	
133	  const addLog = useCallback(
134	    (type: string, message: string, category: LogEntry['category'] = 'info', timestamp?: string) => {
135	      const time = timestamp || new Date().toLocaleTimeString();
136	      const newEntry: LogEntry = {
137	        id: `${Date.now()}-${Math.random()}`,
138	        timestamp: time,
139	        type: type.toUpperCase(),
140	        message,
141	        category,
142	      };
143	
144	      setLogs((prev) => [...prev, newEntry]);
145	    },
146	    []
147	  );
148	
149	  // Fetch initial telemetry
150	  const loadInitialData = async () => {
151	    try {
152	      const [pls, countRes] = await Promise.all([
153	        getCurlerPlaylists(targetProjectId),
154	        executeOrder<{ count: number }>({
155	          project_id: targetProjectId,
156	          tier: '1',
157	          order: { action: 'count' },
158	        }),
159	      ]);
160	
161	      setPlaylists(pls);
162	      setModalPlaylists(pls);
163	      setRawPlaylistText(pls.join('\n'));
164	      if (countRes.data?.count) {
165	        setTotalCatalogCount(countRes.data.count);
166	      }
167	    } catch (e) {
168	      console.warn('Failed to load curler initial metadata:', e);
169	    }
170	  };
171	
172	  useEffect(() => {
173	    loadInitialData();
174	  }, [targetProjectId]);
175	
176	  // Auto-scroll terminal to bottom
177	  useEffect(() => {
178	    if (autoScroll && terminalBottomRef.current) {
179	      terminalBottomRef.current.scrollIntoView({ behavior: 'smooth' });
180	    }
181	  }, [logs, autoScroll]);
182	
183	  // Start Ingestion Streaming
184	  const handleStartIngestion = async () => {
185	    if (isRunning) return;
186	
187	    if (ingestionMode === 'single') {
188	      const cleanUrl = singleUrlInput.trim();
189	      if (!cleanUrl) {
190	        showToast('Please enter a YouTube video or playlist link', 'warn');
191	        return;
192	      }
193	    } else if (playlists.length === 0) {
194	      showToast('No playlists configured in playlists.txt', 'warn');
195	      return;
196	    }
197	
198	    const isSingle = ingestionMode === 'single';
199	    const targetUrls = isSingle ? [singleUrlInput.trim()] : undefined;
200	
201	    setIsRunning(true);
202	    setCurrentProgress({ current: 0, total: isSingle ? 1 : playlists.length });
203	    setTotalScanned(0);
204	    setTotalNewAdded(0);
205	    setTotalGreen(0);
206	    setTotalYellow(0);
207	    setTotalRed(0);
208	    setFinalReport([]);
209	
210	    const controller = new AbortController();
211	    abortControllerRef.current = controller;
212	
213	    addLog(
214	      'INIT',
215	      isSingle
216	        ? `Starting Single Ingestion for: ${singleUrlInput.trim()}`
217	        : `Starting 3-Tier Diagnostic Playlist Ingestion Pipeline...`,
218	      'info'
219	    );
220	
221	    const options: any = {};
222	    if (targetUrls) {
223	      options.urls = targetUrls;
224	    } else if (executionLimit === 'sample') {
225	      options.max_playlists = 4;
226	      options.max_per_playlist = 10;
227	    }
228	
229	    try {
230	      await streamPlaylistIngestion(
231	        options,
232	        (ev: CurlerStreamEvent) => {
233	          if (ev.target_db) {
234	            setTargetDbName(`system/${ev.target_db}`);
235	          }
236	
237	          if (ev.type === 'init') {
238	            if (ev.total_playlists) {
239	              setCurrentProgress({ current: 0, total: ev.total_playlists });
240	            }
241	            if (ev.initial_catalog_count) {
242	              setTotalCatalogCount(ev.initial_catalog_count);
243	            }
244	          } else if (ev.type === 'playlist_start') {
245	            if (ev.index && ev.total) {
246	              setCurrentProgress({ current: ev.index, total: ev.total });
247	            }
248	          } else if (ev.type === 'playlist_done') {
249	            if (ev.category === 'green') setTotalGreen((prev) => prev + 1);
250	            else if (ev.category === 'yellow') setTotalYellow((prev) => prev + 1);
251	            else if (ev.category === 'red') setTotalRed((prev) => prev + 1);
252	
253	            if (ev.total_new_cumulative !== undefined) {
254	              setTotalNewAdded(ev.total_new_cumulative);
255	            }
256	          } else if (ev.type === 'playlist_error') {
257	            setTotalRed((prev) => prev + 1);
258	          } else if (ev.type === 'complete') {
259	            if (ev.total_green !== undefined) setTotalGreen(ev.total_green);
260	            if (ev.total_yellow !== undefined) setTotalYellow(ev.total_yellow);
261	            if (ev.total_red !== undefined) setTotalRed(ev.total_red);
262	            if (ev.total_scanned_videos) setTotalScanned(ev.total_scanned_videos);
263	            if (ev.total_new_added !== undefined) setTotalNewAdded(ev.total_new_added);
264	            if (ev.final_catalog_count) setTotalCatalogCount(ev.final_catalog_count);
265	            if (ev.reports) setFinalReport(ev.reports);
266	
267	            showToast(
268	              `✨ Ingestion finished: 🟢 ${ev.total_green || 0} All Taken | 🟡 +${ev.total_new_added || 0} New Songs | 🔴 ${ev.total_red || 0} Issues.`,
269	              'success'
270	            );
271	          }
272	
273	          if (ev.message) {
274	            const cat =
275	              ev.category === 'green' || ev.category === 'yellow' || ev.category === 'red'
276	                ? ev.category
277	                : 'info';
278	            addLog(ev.status || ev.type, ev.message, cat, ev.timestamp);
279	          }
280	        },
281	        controller.signal
282	      );
283	    } catch (err: any) {
284	      if (err.name === 'AbortError') {
285	        addLog('ABORT', 'Pipeline execution halted by user.', 'yellow');
286	        showToast('Ingestion pipeline stopped.', 'info');
287	      } else {
288	        addLog('ERROR', `Stream pipeline error: ${err.message}`, 'red');
289	        showToast(`Pipeline Error: ${err.message}`, 'error');
290	      }
291	    } finally {
292	      setIsRunning(false);
293	      abortControllerRef.current = null;
294	    }
295	  };
296	
297	  // Stop / Abort Ingestion
298	  const handleStopIngestion = () => {
299	    if (abortControllerRef.current) {
300	      abortControllerRef.current.abort();
301	    }
302	  };
303	
304	  // Clear Terminal Logs
305	  const handleClearLogs = () => {
306	    setLogs([]);
307	  };
308	
309	  // Open Playlist Manager
310	  const handleOpenPlaylistManager = () => {
311	    setModalPlaylists([...playlists]);
312	    setRawPlaylistText(playlists.join('\n'));
313	    setNewPlaylistInput('');
314	    setShowPlaylistModal(true);
315	  };
316	
317	  // Add a single Playlist to modal list
318	  const handleAddPlaylist = () => {
319	    const clean = newPlaylistInput.trim();
320	    if (!clean) {
321	      showToast('Please enter a YouTube playlist URL or ID', 'error');
322	      return;
323	    }
324	
325	    if (modalPlaylists.includes(clean)) {
326	      showToast('This playlist is already in the list!', 'error');
327	      return;
328	    }
329	
330	    const updated = [...modalPlaylists, clean];
331	    setModalPlaylists(updated);
332	    setRawPlaylistText(updated.join('\n'));
333	    setNewPlaylistInput('');
334	    showToast(`Added playlist: ${extractPlaylistId(clean)}`, 'success');
335	  };
336	
337	  // Delete a Playlist from modal list
338	  const handleDeletePlaylist = (indexToDelete: number) => {
339	    const updated = modalPlaylists.filter((_, idx) => idx !== indexToDelete);
340	    setModalPlaylists(updated);
341	    setRawPlaylistText(updated.join('\n'));
342	    showToast('Playlist removed from configuration', 'info');
343	  };
344	
345	  // Save Playlists to playlists.txt
346	  const handleSavePlaylists = async () => {
347	    setIsSavingPlaylists(true);
348	    try {
349	      let urlsToSave: string[] = [];
350	      if (managerMode === 'interactive') {
351	        urlsToSave = modalPlaylists;
352	      } else {
353	        urlsToSave = rawPlaylistText
354	          .split('\n')
355	          .map((l) => l.trim())
356	          .filter((l) => l.length > 0 && !l.startsWith('#'));
357	      }
358	
359	      // Deduplicate preserving order
360	      const seen = new Set<string>();
361	      const finalUrls: string[] = [];
362	      for (const u of urlsToSave) {
363	        if (!seen.has(u)) {
364	          seen.add(u);
365	          finalUrls.push(u);
366	        }
367	      }
368	
369	      const ok = await saveCurlerPlaylists(targetProjectId, finalUrls);
370	      if (ok) {
371	        setPlaylists(finalUrls);
372	        setModalPlaylists(finalUrls);
373	        setRawPlaylistText(finalUrls.join('\n'));
374	        showToast(`💾 Saved ${finalUrls.length} playlists to playlists.txt!`, 'success');
375	        setShowPlaylistModal(false);
376	        addLog('CONFIG', `Updated playlists.txt with ${finalUrls.length} unique playlist entries.`, 'info');
377	      } else {
378	        showToast('Failed to save playlist configurations.', 'error');
379	      }
380	    } catch (e: any) {
381	      showToast(`Error saving playlists: ${e.message}`, 'error');
382	    } finally {
383	      setIsSavingPlaylists(false);
384	    }
385	  };
386	
387	  // Filtered reports for the report drawer
388	  const filteredReports = useMemo(() => {
389	    if (reportFilter === 'all') return finalReport;
390	    return finalReport.filter((r) => r.category === reportFilter);
391	  }, [finalReport, reportFilter]);
392	
393	  const progressPercent =
394	    currentProgress.total > 0
395	      ? Math.round((currentProgress.current / currentProgress.total) * 100)
396	      : 0;
397	
398	  return (
399	    <div className="space-y-6 max-w-7xl mx-auto w-full">
400	      {/* Toast Overlay */}
401	      {toast && (
402	        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-6 py-3.5 rounded-2xl bg-[#171320] border border-[#d4af37] text-xs font-semibold shadow-2xl flex items-center justify-center gap-2 animate-in fade-in slide-in-from-bottom-2 text-[#ffd86b]">
403	          {toast.type === 'success' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
404	          {toast.type === 'error' && <AlertCircle className="w-4 h-4 text-rose-400" />}
405	          {toast.type === 'info' && <Sparkles className="w-4 h-4 text-[#ffd86b]" />}
406	          <span>{toast.message}</span>
407	        </div>
408	      )}
409	
410	      {/* Header & Status Dashboard */}
411	      <div className="p-6 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-2xl space-y-4">
412	        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
413	          <div className="flex items-center gap-3.5">
414	            <div className="p-3.5 rounded-2xl bg-gradient-to-br from-[#291e07] to-[#120f18] border border-[#524124] text-[#ffd86b] shadow-inner">
415	              <DownloadCloud className="w-7 h-7" />
416	            </div>
417	            <div>
418	              <div className="flex items-center gap-2.5">
419	                <h2 className="font-cinzel text-xl font-bold text-[#ffd86b]">
420	                  Song Ingestion & Diagnostic Lab
421	                </h2>
422	                <span
423	                  className={`px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold uppercase border ${
424	                    isRunning
425	                      ? 'bg-amber-950/80 text-amber-300 border-amber-500 animate-pulse'
426	                      : 'bg-[#1a1424] text-[#8c7a9e] border-[#3d304f]'
427	                  }`}
428	                >
429	                  {isRunning ? '● Ingesting Stream' : '○ Standby'}
430	                </span>
431	              </div>
432	              <p className="text-xs text-[#8c7a9e] mt-1 leading-relaxed">
433	                Outputs directly to{' '}
434	                <code className="text-[#ffd86b] font-mono bg-black/50 px-1.5 py-0.5 rounded border border-[#3d304f]">
435	                  backend/data/projects/music_app/app_data/{targetDbName}
436	                </code>
437	                . Live 3-Tier diagnostic feedback per playlist.
438	              </p>
439	            </div>
440	          </div>
441	
442	          {/* Quick Navigation Buttons */}
443	          <div className="flex items-center gap-2 self-stretch md:self-auto justify-end">
444	            {onNavigateToGameplay && (
445	              <button
446	                type="button"
447	                onClick={onNavigateToGameplay}
448	                className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-cinzel font-bold bg-[#1a1424] hover:bg-[#251d33] border border-[#3d304f] text-[#cbd5e1] hover:text-[#ffd86b] transition cursor-pointer"
449	              >
450	                <Disc3 className="w-4 h-4 text-[#ffd86b]" />
451	                <span>To Gameplay</span>
452	              </button>
453	            )}
454	            {onNavigateToGallery && (
455	              <button
456	                type="button"
457	                onClick={onNavigateToGallery}
458	                className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-cinzel font-bold bg-[#1a1424] hover:bg-[#251d33] border border-[#3d304f] text-[#cbd5e1] hover:text-[#ffd86b] transition cursor-pointer"
459	              >
460	                <Layers className="w-4 h-4 text-[#ffd86b]" />
461	                <span>To Gallery</span>
462	              </button>
463	            )}
464	          </div>
465	        </div>
466	
467	        {/* 3-Tier Diagnostic Diagnostic Bar */}
468	        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 pt-2 border-t border-[#1e1728]">
469	          {/* Sound Pool Total */}
470	          <div className="p-3.5 rounded-xl bg-[#0f0d14] border border-[#2b2238] space-y-1">
471	            <span className="text-[10px] font-mono text-[#8c7a9e] uppercase flex items-center gap-1.5">
472	              <Database className="w-3.5 h-3.5 text-[#ffd86b]" /> Sound Pool Total
473	            </span>
474	            <p className="text-base font-bold font-mono text-white">
475	              {totalCatalogCount > 0 ? `${totalCatalogCount.toLocaleString()} Songs` : 'Loading...'}{' '}
476	              {totalScanned > 0 && (
477	                <span className="text-[11px] font-normal text-[#8c7a9e]">
478	                  ({totalScanned} scanned)
479	                </span>
480	              )}
481	            </p>
482	          </div>
483	
484	          {/* 🟢 Green State: All Songs Taken */}
485	          <div className="p-3.5 rounded-xl bg-[#0b1a12] border border-emerald-900/60 space-y-1">
486	            <span className="text-[10px] font-mono text-emerald-400 uppercase flex items-center gap-1.5 font-bold">
487	              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" /> 🟢 All Songs Taken
488	            </span>
489	            <p className="text-base font-bold font-mono text-emerald-300">
490	              {totalGreen} Playlists{' '}
491	              <span className="text-xs font-normal text-emerald-500">(100% Synced)</span>
492	            </p>
493	          </div>
494	
495	          {/* 🟡 Yellow State: Curled New Songs */}
496	          <div className="p-3.5 rounded-xl bg-[#1f1b0a] border border-amber-900/60 space-y-1">
497	            <span className="text-[10px] font-mono text-amber-400 uppercase flex items-center gap-1.5 font-bold">
498	              <Sparkles className="w-3.5 h-3.5 text-amber-400" /> 🟡 Curled New Songs
499	            </span>
500	            <p className="text-base font-bold font-mono text-amber-300">
501	              {totalYellow} Lists{' '}
502	              <span className="text-xs font-normal text-amber-400">(+{totalNewAdded} songs)</span>
503	            </p>
504	          </div>
505	
506	          {/* 🔴 Red State: Issues / Unavailable */}
507	          <div className="p-3.5 rounded-xl bg-[#1c0d12] border border-rose-900/60 space-y-1">
508	            <span className="text-[10px] font-mono text-rose-400 uppercase flex items-center gap-1.5 font-bold">
509	              <AlertCircle className="w-3.5 h-3.5 text-rose-400" /> 🔴 Unavailable / Failed
510	            </span>
511	            <p className="text-base font-bold font-mono text-rose-300">
512	              {totalRed} Lists{' '}
513	              <span className="text-xs font-normal text-rose-400">(404 or Private)</span>
514	            </p>
515	          </div>
516	        </div>
517	
518	        {/* Real-time Progress Bar */}
519	        {isRunning && (
520	          <div className="space-y-1.5 pt-2">
521	            <div className="flex items-center justify-between text-xs font-mono text-[#8c7a9e]">
522	              <span>Ingestion Progress:</span>
523	              <span className="text-[#ffd86b] font-bold">
524	                Playlist {currentProgress.current} / {currentProgress.total} ({progressPercent}%)
525	              </span>
526	            </div>
527	            <div className="w-full h-2.5 bg-[#1a1424] rounded-full overflow-hidden border border-[#2b2238]">
528	              <div
529	                className="h-full bg-gradient-to-r from-[#d4af37] via-[#ffd86b] to-[#f59e0b] rounded-full transition-all duration-300 shadow-gold-sm"
530	                style={{ width: `${progressPercent}%` }}
531	              />
532	            </div>
533	          </div>
534	        )}
535	      </div>
536	
537	      {/* Ingestion Mode Selector: Batch (Library) vs Single (One-Time Link) */}
538	      <div className="p-4 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-lg space-y-3">
539	        <div className="flex items-center justify-between border-b border-[#231b2e] pb-2.5">
540	          <div className="flex items-center gap-2">
541	            <Radio className="w-4 h-4 text-[#ffd86b]" />
542	            <span className="font-cinzel text-xs font-bold text-white uppercase tracking-wider">
543	              Ingestion Mode
