1033	                    className="w-full bg-[#0a080f] border border-[#332842] focus:border-[#d4af37] rounded-xl p-3.5 text-xs font-mono text-[#f5f0e8] focus:outline-none transition leading-relaxed placeholder-[#524124]"
1034	                  />
1035	                </div>
1036	              )}
