1039	            {/* Modal Footer */}
1040	            <div className="p-4 border-t border-[#292033] bg-[#0d0a12] flex items-center justify-between">
1041	              <span className="text-xs font-mono text-[#8c7a9e]">
1042	                {managerMode === 'interactive'
1043	                  ? `${modalPlaylists.length} Playlists configured`
1044	                  : `${rawPlaylistText.split('\n').filter((l) => l.trim().length > 0 && !l.trim().startsWith('#')).length} Playlists in text`}
1045	              </span>
1046	
1047	              <div className="flex items-center gap-2">
1048	                <button
1049	                  type="button"
