export async function streamPlaylistIngestion(
  options: {
    urls?: string[];
    max_playlists?: number;
    max_per_playlist?: number;
  },
  onEvent: (event: CurlerStreamEvent) => void,
  signal?: AbortSignal
): Promise<void> {
  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(options),
    signal,
  });

  if (!res.ok) {
    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
  }

  if (!res.body) {
    throw new Error('ReadableStream not supported on response body.');
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder('utf-8');
  let buffer = '';

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const chunks = buffer.split('\n\n');
    buffer = chunks.pop() || '';

    for (const chunk of chunks) {
      const trimmed = chunk.trim();
      if (trimmed.startsWith('data:')) {
        try {
          const jsonStr = trimmed.slice(5).trim();
          if (jsonStr) {
            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
            onEvent(eventData);
          }
        } catch (err) {
          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
        }
      }
    }
  }

  if (buffer.trim().startsWith('data:')) {
    try {
      const jsonStr = buffer.trim().slice(5).trim();
      if (jsonStr) {
        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
        onEvent(eventData);
      }
    } catch (_) {}
  }

  // Clear static caches after streaming completes
  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
  invalidateVinylCache();
}

# backend/api/curler_router.py — SSE Streaming Router for Vinyl Angel Curler
import json
from typing import Optional
from fastapi import APIRouter, Request
from fastapi.responses import StreamingResponse
from integrations.curler.curler_service import stream_playlist_curl

router = APIRouter(prefix="/api/v1/curler", tags=["Playlist Curler"])

@router.post("/stream")
@router.get("/stream")
async def curler_stream_endpoint(request: Request):
    """
    Real-time Server-Sent Events (SSE) streaming endpoint for playlist curler ingestion.
    Emits live logs, playlist progress, and metadata insertion events.
    """
    urls = None
    max_playlists = None
    max_per_playlist = None

    if request.method == "POST":
        try:
            body = await request.json()
            urls = body.get("urls")
            max_playlists = body.get("max_playlists")
            max_per_playlist = body.get("max_per_playlist")
        except Exception:
            pass
    else:
        max_pl_param = request.query_params.get("max_playlists")
        if max_pl_param and max_pl_param.isdigit():
            max_playlists = int(max_pl_param)
        max_per_param = request.query_params.get("max_per_playlist")
        if max_per_param and max_per_param.isdigit():
            max_per_playlist = int(max_per_param)

    def event_generator():
        for event in stream_playlist_curl(urls, max_playlists, max_per_playlist):
            yield f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )

